<?php require_role('admin');require_once 'app/helpers.php';$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$d=[(int)$_POST['topic_id'],trim($_POST['title_en']),trim($_POST['title_ta']),(int)$_POST['sort_order']];if($id){$s=db()->prepare('UPDATE subtopics SET topic_id=?,title_en=?,title_ta=?,sort_order=? WHERE id=?');$s->execute([...$d,$id]);}else{$s=db()->prepare('INSERT INTO subtopics(topic_id,title_en,title_ta,sort_order) VALUES(?,?,?,?)');$s->execute($d);}header('Location: admin.php');exit;}$topics=db()->query('SELECT id,title_en,audience FROM topics ORDER BY audience,sort_order')->fetchAll();$t=$id?db()->query('SELECT * FROM subtopics WHERE id='.$id)->fetch():['topic_id'=>(int)($_GET['topic_id']??0),'title_en'=>'','title_ta'=>'','sort_order'=>1];$page_title='Subtopic Editor';include 'partials/header.php';?><div class="card"><h1><?=($id?'Edit':'Add')?> Subtopic</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-group"><label>Topic</label><select name="topic_id" required><?php foreach($topics as $x):?><option value="<?=$x['id']?>" <?=$t['topic_id']==$x['id']?'selected':''?>><?=e($x['audience'].' – '.$x['title_en'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Title (English)</label><input name="title_en" value="<?=e($t['title_en'])?>" required></div><div class="form-group"><label>Title (Tamil)</label><input name="title_ta" value="<?=e($t['title_ta'])?>"></div><div class="form-group"><label>Sort order</label><input type="number" name="sort_order" value="<?=e($t['sort_order'])?>"></div><button class="btn">Save</button> <a class="btn secondary" href="admin.php">Cancel</a></form></div><?php include 'partials/footer.php';?>
